package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.util.ContextualTypeResolver;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for MappingIterator#nextValue().
 * Note: Since MappingIterator is a complex class with many private fields, 
 * we use Mockito to simulate the internal dependencies and use reflection 
 * or subclassing to manipulate the protected/private state for high coverage.
 */
public class MappingIterator_nextValue_TriageGen1Test {

    private TestableMappingIterator<String> iterator;
    private JsonParser mockParser;
    private TestDeserializer<String> mockDeserializer;
    private MappingContext mockContext;

    // Constants to match internal state if possible, or simulate via subclass
    private static final int STATE_CLOSED = 0;
    private static final int STATE_NEED_RESYNC = 1;
    private static final int STATE_MAY_HAVE_VALUE = 2;
    private static final int STATE_HAS_VALUE = 3;

    /**
     * Subclass to expose protected fields and methods for testing purposes.
     */
    private static class TestableMappingIterator<T> extends MappingIterator<T> {
        int _state;
        T _updatedValue;
        TestDeserializer<T> _deserializer;
        JsonParser _parser;
        MappingContext _context;
        boolean hasNextValueResult = true;

        public TestableMappingIterator(JsonParser parser, TestDeserializer<T> deserializer, MappingContext context) {
            super(parser, deserializer, context);
            this._parser = parser;
            this._deserializer = deserializer;
            this._context = context;
        }

        // We override/inject via reflection in the test or use these fields
        @Override
        public boolean hasNextValue() throws IOException {
            return hasNextValueResult;
        }

        @Override
        protected <R> R _throwNoSuchElement() throws IOException {
            throw new java.util.NoSuchElementException("No such element");
        }

        // Helper to set state via reflection because it's private
        public void setState(int state) {
            this._state = state;
        }

        public void setHasNextValue(boolean val) {
            this.hasNextValueResult = val;
        }

        public void setUpdatedValue(T value) {
            this._updatedValue = value;
        }
    }

    private static class TestDeserializer<T> extends StdDeserializer<T> {
        protected T valueToReturn;
        protected boolean throwException = false;

        protected TestDeserializer() {
            super(Object.class);
        }

        @Override
        public T deserialize(com.fasterxml.jackson.core.JsonParser p, com.fasterxml.jackson.databind.DeserializationContext ctxt) throws IOException {
            if (throwException) throw new IOException("Deserialization failed");
            return valueToReturn;
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockDeserializer = new TestDeserializer<>();
        mockContext = mock(MappingContext.class);
        iterator = new TestableMappingIterator<>(mockParser, mockDeserializer, mockContext);
    }

    @Test
    public void testNextValue_StateClosed_ThrowsException() {
        iterator.setState(STATE_CLOSED);
        try {
            iterator.nextValue();
            org.junit.Assert.fail("Should have thrown NoSuchElementException");
        } catch (java.util.NoSuchElementException e) {
            // Success
        } catch (IOException e) {
            org.junit.Assert.fail("Wrong exception type");
        }
    }

    @Test
    public void testNextValue_StateNeedResync_NoHasNextValue_ThrowsException() throws IOException {
        iterator.setState(STATE_NEED_RESYNC);
        iterator.setHasNextValue(false);
        try {
            iterator.nextValue();
            org.junit.Assert.fail("Should have thrown NoSuchElementException");
        } catch (java.util.NoSuchElementException e) {
            // Success
        } catch (IOException e) {
            org.junit.Assert.fail("Wrong exception type");
        }
    }

    @Test
    public void testNextValue_StateMayHaveValue_NoHasNextValue_ThrowsException() throws IOException {
        iterator.setState(STATE_MAY_HAVE_VALUE);
        iterator.setHasNextValue(false);
        try {
            iterator.nextValue();
            org.junit.Assert.fail("Should have thrown NoSuchElementException");
        } catch (java.util.NoSuchElementException e) {
            // Success
        } catch (IOException e) {
            org.junit.Assert.fail("Wrong exception type");
        }
    }

    @Test
    public void testNextValue_StateHasValue_DeserializesSuccessfully() throws IOException {
        iterator.setState(STATE_HAS_VALUE);
        mockDeserializer.valueToReturn = "Success";

        String result = iterator.nextValue();

        assertEquals("Success", result);
        verify(mockParser).clearCurrentToken();
    }

    @Test
    public void testNextValue_StateMayHaveValue_DeserializesSuccessfully() throws IOException {
        iterator.setState(STATE_MAY_HAVE_VALUE);
        iterator.setHasNextValue(true);
        mockDeserializer.valueToReturn = "ValueFromParser";

        String result = iterator.nextValue();

        assertEquals("ValueFromParser", result);
        verify(mockParser).clearCurrentToken();
    }

    @Test
    public void testNextValue_UsesUpdatedValue() throws IOException {
        iterator.setState(STATE_HAS_VALUE);
        iterator.setUpdatedValue("Updated");

        String result = iterator.nextValue();

        assertEquals("Updated", result);
        verify(mockDeserializer, never()).deserialize(any(), any());
        verify(mockParser).clearCurrentToken();
    }

    @Test
    public void testNextValue_DeserializationFailure_SetsStateAndClearsToken() throws IOException {
        iterator.setState(STATE_HAS_VALUE);
        mockDeserializer.throwException = true;

        try {
            iterator.nextValue();
            org.junit.Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("Deserialization failed", e.getMessage());
        }

        // Verify finally block execution
        verify(mockParser).clearCurrentToken();
        // Internal state should be set to nextState (STATE_NEED_RESYNC) even on failure
        assertEquals(STATE_NEED_RESYNC, iterator._state);
    }

    @Test
    public void testNextValue_StateNeedResync_DeserializesSuccessfully() throws IOException {
        iterator.setState(STATE_NEED_RESYNC);
        iterator.setHasNextValue(true);
        mockDeserializer.valueToReturn = "ResyncValue";

        String result = iterator.nextValue();

        assertEquals("ResyncValue", result);
        verify(mockParser).clearCurrentToken();
    }
}
